export default "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <meta name=\"description\" content=\"给中小微企业主使用的财富管理驾驶舱：看清资产、利润、现金安全和下一步行动。\" />\n  <meta name=\"theme-color\" content=\"#10221d\" />\n  <title>老板财富驾驶舱</title>\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='15' fill='%2310221d'/%3E%3Cpath d='M15 43V24h8v19zm13 0V15h8v28zm13 0V29h8v14z' fill='%23e9c46a'/%3E%3Cpath d='M12 48h40' stroke='%23fff' stroke-width='4' stroke-linecap='round'/%3E%3C/svg%3E\" />\n  <style>\n    :root{--ink:#17211d;--muted:#69736f;--paper:#f5f6f2;--card:#fff;--deep:#10221d;--green:#1e6b50;--mint:#d9f2e7;--gold:#e4b94f;--red:#c94a48;--redsoft:#fae5e3;--line:#dfe4df;--shadow:0 18px 50px rgba(20,41,33,.08);--radius:22px}\n    *{box-sizing:border-box} body{margin:0;background:var(--paper);color:var(--ink);font-family:\"Microsoft YaHei\",\"PingFang SC\",system-ui,sans-serif;font-size:16px;line-height:1.5} button,input{font:inherit} button{cursor:pointer}\n    .app{min-height:100vh;display:grid;grid-template-columns:240px 1fr}.sidebar{background:var(--deep);color:#fff;padding:28px 20px;position:sticky;top:0;height:100vh;display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:12px;font-size:1.18rem;font-weight:800;margin:0 8px 38px}.brand-mark{width:38px;height:38px;border-radius:12px;background:var(--gold);color:var(--deep);display:grid;place-items:center;font-weight:900}.nav{display:grid;gap:8px}.nav button{border:0;background:transparent;color:#b9c7c1;padding:12px 14px;border-radius:12px;text-align:left;display:flex;align-items:center;gap:11px}.nav button:hover,.nav button.active{background:#203b32;color:#fff}.nav button.active{box-shadow:inset 3px 0 var(--gold)}.nav svg{width:19px;height:19px}.side-note{margin-top:auto;background:#19372d;padding:16px;border:1px solid #2c4b40;border-radius:16px;color:#c6d4ce;font-size:.86rem}.side-note strong{display:block;color:#fff;margin-bottom:4px}.main{padding:28px 34px 56px;max-width:1500px;width:100%;margin:auto}.topbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.eyebrow{color:var(--green);font-weight:700;font-size:.86rem;letter-spacing:.05em;margin:0 0 3px}.topbar h1{font-size:1.7rem;margin:0;letter-spacing:-.04em}.actions{display:flex;gap:10px}.btn{border:1px solid var(--line);border-radius:12px;background:#fff;padding:10px 15px;font-weight:700;color:var(--ink)}.btn:hover{transform:translateY(-1px)}.btn.primary{background:var(--green);border-color:var(--green);color:#fff}.status-strip{display:flex;gap:10px;align-items:center;background:#eaf4ef;border:1px solid #cde4d8;border-radius:16px;padding:12px 16px;margin-bottom:18px}.status-dot{width:9px;height:9px;background:#2b946e;border-radius:50%;box-shadow:0 0 0 5px rgba(43,148,110,.12)}.status-strip strong{margin-right:4px}.status-strip .updated{margin-left:auto;color:var(--muted);font-size:.82rem}\n    .metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.metric{background:var(--card);border:1px solid #e5e9e5;border-radius:var(--radius);padding:19px;box-shadow:0 6px 25px rgba(25,48,39,.035);position:relative;overflow:hidden}.metric .label{color:var(--muted);font-size:.9rem}.metric .value{font-size:1.75rem;font-weight:850;letter-spacing:-.05em;margin:6px 0 7px}.metric .sub{font-size:.82rem;color:var(--muted)}.metric .trend{color:var(--green);font-weight:700}.metric.risk .trend{color:var(--red)}.metric .mini{position:absolute;right:15px;top:16px;border-radius:10px;background:#eef6f2;color:var(--green);width:34px;height:34px;display:grid;place-items:center;font-size:.88rem;font-weight:800}\n    .grid{display:grid;grid-template-columns:1.2fr .8fr;gap:16px;margin-top:16px}.card{background:var(--card);border:1px solid #e5e9e5;border-radius:var(--radius);padding:22px;box-shadow:var(--shadow)}.card-head{display:flex;justify-content:space-between;gap:12px;align-items:start;margin-bottom:18px}.card h2{font-size:1.08rem;margin:0}.card-head p{color:var(--muted);font-size:.82rem;margin:4px 0 0}.pill{border:0;border-radius:999px;padding:6px 10px;background:#eef6f2;color:var(--green);font-weight:700;font-size:.78rem}.money-layout{display:grid;grid-template-columns:190px 1fr;align-items:center;gap:20px}.donut{width:168px;height:168px;border-radius:50%;background:conic-gradient(var(--green) 0 48%,var(--gold) 48% 66%,#6aa694 66% 83%,#c8d1cc 83%);display:grid;place-items:center;position:relative}.donut:after{content:\"\";position:absolute;width:105px;height:105px;background:#fff;border-radius:50%}.donut-center{z-index:1;text-align:center}.donut-center b{font-size:1.2rem;display:block}.donut-center span{font-size:.75rem;color:var(--muted)}.legend{display:grid;gap:12px}.legend-row{display:grid;grid-template-columns:12px 1fr auto;gap:9px;align-items:center}.legend-row i{width:9px;height:9px;border-radius:3px}.legend-row span{font-size:.88rem;color:var(--muted)}.legend-row b{font-size:.9rem}.safety{display:grid;grid-template-columns:132px 1fr;gap:22px;align-items:center}.score-ring{width:128px;height:128px;border-radius:50%;background:conic-gradient(var(--green) 0 78%,#e5ebe7 78%);display:grid;place-items:center;position:relative}.score-ring:after{content:\"\";position:absolute;inset:12px;background:#fff;border-radius:50%}.score{z-index:1;text-align:center}.score b{font-size:2rem;display:block;line-height:1}.score small{color:var(--muted)}.checks{display:grid;gap:10px}.check{display:flex;gap:10px;align-items:center;font-size:.9rem}.check-icon{width:24px;height:24px;border-radius:8px;display:grid;place-items:center;background:var(--mint);color:var(--green);font-weight:bold}.check.warn .check-icon{background:#fff0cc;color:#9b6b00}.progress{height:8px;background:#e8ece9;border-radius:10px;overflow:hidden;margin-top:6px}.progress span{display:block;height:100%;background:var(--green);border-radius:10px}.cash-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:11px}.cash-item{background:#f7f9f7;border-radius:15px;padding:14px}.cash-item span{font-size:.78rem;color:var(--muted);display:block}.cash-item b{font-size:1.12rem}.runway{margin-top:16px;padding-top:14px;border-top:1px solid var(--line)}.runway-top{display:flex;justify-content:space-between}.runway b{color:var(--green)}.alert-card{background:var(--deep);color:#fff}.alert-card .card-head p{color:#aebeb7}.tasks{display:grid;gap:10px}.task{display:grid;grid-template-columns:34px 1fr auto;gap:11px;align-items:center;background:#1a342b;border:1px solid #29463c;padding:12px;border-radius:14px}.task-num{width:30px;height:30px;border-radius:9px;background:var(--gold);color:var(--deep);font-weight:850;display:grid;place-items:center}.task b{font-size:.91rem;display:block}.task small{color:#aebeb7}.task button{background:transparent;color:#fff;border:1px solid #537066;border-radius:9px;padding:6px 9px}.wide{grid-column:1/-1}.flow-row{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px}.flow{padding:16px;border-radius:16px;background:#f7f9f7}.flow span{font-size:.8rem;color:var(--muted)}.flow b{display:block;font-size:1.2rem}.flow.negative b{color:var(--red)}\n    .section{display:none}.section.active{display:block}.form-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.form-group{background:#f7f9f7;border:1px solid #e5e9e5;border-radius:16px;padding:15px}.form-group label{font-size:.83rem;color:var(--muted);font-weight:700;display:block;margin-bottom:7px}.input-wrap{display:flex;align-items:center;background:#fff;border:1px solid #d9dfda;border-radius:10px;padding:0 11px}.input-wrap:focus-within{outline:3px solid rgba(30,107,80,.12);border-color:var(--green)}.input-wrap span{color:var(--muted)}.input-wrap input{width:100%;border:0;outline:0;padding:10px 7px;background:transparent;font-weight:700}.form-section{margin-bottom:20px}.form-section h3{font-size:1rem;margin:0 0 10px}.form-footer{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}.table-wrap{overflow-x:auto}.data-table{width:100%;border-collapse:collapse}.data-table th,.data-table td{text-align:left;padding:13px 10px;border-bottom:1px solid var(--line);white-space:nowrap}.data-table th{font-size:.78rem;color:var(--muted)}.data-table td{font-size:.9rem}.tag{display:inline-block;border-radius:999px;padding:4px 9px;font-size:.75rem;font-weight:700}.tag.red{background:var(--redsoft);color:var(--red)}.tag.green{background:var(--mint);color:var(--green)}.empty{padding:38px;text-align:center;color:var(--muted)}.privacy{font-size:.8rem;color:var(--muted);margin-top:12px}.toast{position:fixed;right:24px;bottom:24px;background:var(--deep);color:#fff;border-radius:13px;padding:13px 18px;box-shadow:var(--shadow);transform:translateY(100px);opacity:0;transition:.25s;z-index:20}.toast.show{transform:none;opacity:1}\n    @media(max-width:1050px){.app{grid-template-columns:82px 1fr}.sidebar{padding:24px 12px}.brand span,.nav span,.side-note{display:none}.brand{margin-left:9px}.nav button{justify-content:center}.metric-grid{grid-template-columns:repeat(2,1fr)}.money-layout{grid-template-columns:165px 1fr}}\n    @media(max-width:720px){.app{display:block}.sidebar{height:auto;position:fixed;z-index:10;bottom:0;top:auto;width:100%;padding:8px;background:rgba(16,34,29,.97)}.brand,.side-note{display:none}.nav{grid-template-columns:repeat(4,1fr)}.nav button{padding:9px 4px;display:grid;justify-items:center;gap:2px;font-size:.68rem}.nav span{display:block}.main{padding:20px 15px 94px}.topbar{align-items:start}.topbar h1{font-size:1.35rem}.actions .btn:not(.primary){display:none}.status-strip{font-size:.82rem}.status-strip .updated{display:none}.metric-grid,.grid,.form-grid,.flow-row{grid-template-columns:1fr}.money-layout,.safety{grid-template-columns:1fr;justify-items:center}.legend{width:100%}.wide{grid-column:auto}.cash-grid{grid-template-columns:1fr 1fr 1fr}.metric .value{font-size:1.55rem}}\n  </style>\n  <style>\n    [hidden]{display:none!important}.login-gate{min-height:100vh;display:grid;place-items:center;padding:24px;background:radial-gradient(circle at 50% 0,#d9f2e7 0,transparent 42%),var(--deep)}.login-box{max-width:620px;background:#fff;border-radius:28px;padding:46px;text-align:center;box-shadow:0 35px 90px rgba(0,0,0,.28)}.login-box .brand-mark{margin:0 auto 18px;width:62px;height:62px;font-size:1.5rem}.login-box h1{font-size:2.1rem;letter-spacing:-.05em;margin:8px 0 14px}.login-box p{color:var(--muted);line-height:1.8}.login-box .primary{display:inline-block;text-decoration:none;margin-top:10px;padding:14px 26px}.trust{display:flex;justify-content:center;gap:16px;margin-top:25px;font-size:.8rem;color:var(--muted)}.account{margin-top:auto;background:#19372d;border:1px solid #2c4b40;border-radius:15px;padding:14px;display:grid;gap:3px}.account strong{color:#fff}.account small{color:#aebeb7;overflow:hidden;text-overflow:ellipsis}.account a{color:#f0cf79;font-size:.78rem;margin-top:6px}.month-picker{border:1px solid var(--line);border-radius:11px;padding:9px;background:#fff}.history-list{display:grid;gap:10px}.history-item{display:grid;grid-template-columns:1.2fr 1fr 1fr auto;align-items:center;gap:14px;border:1px solid var(--line);background:#f8faf8;border-radius:14px;padding:14px;text-align:left}.history-item span{display:grid}.history-item small{color:var(--muted)}.history-item em{font-style:normal;color:var(--green);font-weight:700}.empty-state{text-align:center;padding:45px;color:var(--muted)}\n    @media(max-width:1050px){.account strong,.account small,.account a{display:none}.account{height:52px}.nav{gap:5px}}\n    @media(max-width:720px){.nav{grid-template-columns:repeat(5,1fr)}.login-box{padding:34px 23px}.login-box h1{font-size:1.65rem}.trust{display:grid;gap:7px}.month-picker{width:132px}.history-item{grid-template-columns:1fr 1fr}.history-item span:nth-child(3),.history-item em{display:none}}\n  </style>\n</head>\n<body>\n<div class=\"login-gate\" id=\"loginGate\"><section class=\"login-box\"><div class=\"brand-mark\">财</div><p class=\"eyebrow\">老板财富驾驶舱</p><h1>不懂财务，也能管好自己的财富</h1><p>每位老板使用自己的账号，财务数据独立保存。换手机、换电脑，登录后仍可继续查看。</p><a class=\"btn primary\" href=\"/signin-with-chatgpt?return_to=/\">登录并开始使用</a><div class=\"trust\"><span>✓ 独立账号</span><span>✓ 云端保存</span><span>✓ 数据隔离</span></div></section></div>\n<div class=\"app\" id=\"app\" hidden>\n  <aside class=\"sidebar\">\n    <div class=\"brand\"><div class=\"brand-mark\">财</div><span>老板财富驾驶舱</span></div>\n    <nav class=\"nav\" aria-label=\"主要导航\">\n      <button class=\"active\" data-target=\"dashboard\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\"/></svg><span>总览</span></button>\n      <button data-target=\"input\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4z\"/></svg><span>更新数字</span></button>\n      <button data-target=\"receivables\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M8 12h8M12 8v8\"/></svg><span>收款与负债</span></button>\n      <button data-target=\"history\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 12a9 9 0 1 0 3-6.7L3 8\"/><path d=\"M3 3v5h5M12 7v5l3 2\"/></svg><span>历史记录</span></button>\n      <button data-target=\"guide\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"/><path d=\"M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z\"/></svg><span>老板使用指南</span></button>\n    </nav>\n    <div class=\"account\"><strong id=\"userName\">老板</strong><small id=\"userEmail\"></small><a href=\"/signout-with-chatgpt?return_to=/\">退出登录</a></div>\n  </aside>\n\n  <main class=\"main\">\n    <section id=\"dashboard\" class=\"section active\">\n      <header class=\"topbar\"><div><p class=\"eyebrow\" id=\"today\"></p><h1>老板，今天的钱，心里有数。</h1></div><div class=\"actions\"><input class=\"month-picker\" id=\"monthPicker\" type=\"month\" aria-label=\"选择月份\"><button class=\"btn\" id=\"resetDemo\">查看示例</button><button class=\"btn primary\" data-go=\"input\">更新本月数字</button></div></header>\n      <div class=\"status-strip\"><span class=\"status-dot\"></span><div><strong id=\"statusTitle\">整体安全</strong><span id=\"statusText\">现金充足，但有两笔客户欠款需要跟进。</span></div><span class=\"updated\" id=\"updatedTime\">示例数据</span></div>\n      <div class=\"metric-grid\">\n        <article class=\"metric\"><span class=\"label\">你真正拥有的财富</span><div class=\"value\" id=\"netWorth\">¥0</div><div class=\"sub\">总资产减去全部欠款 <span class=\"trend\" id=\"netWorthTrend\">健康</span></div><span class=\"mini\">净</span></article>\n        <article class=\"metric\"><span class=\"label\">公司本月真正赚到</span><div class=\"value\" id=\"profit\">¥0</div><div class=\"sub\">净利润率 <span class=\"trend\" id=\"margin\">0%</span></div><span class=\"mini\">赚</span></article>\n        <article class=\"metric\"><span class=\"label\">手头可立即使用的钱</span><div class=\"value\" id=\"cash\">¥0</div><div class=\"sub\">预计能支撑 <span class=\"trend\" id=\"runwayMini\">0个月</span></div><span class=\"mini\">现</span></article>\n        <article class=\"metric risk\"><span class=\"label\">别人还欠你的钱</span><div class=\"value\" id=\"receivable\">¥0</div><div class=\"sub\">其中逾期 <span class=\"trend\" id=\"overdue\">¥0</span></div><span class=\"mini\">收</span></article>\n      </div>\n\n      <div class=\"grid\">\n        <article class=\"card\"><div class=\"card-head\"><div><h2>财富装在哪些口袋</h2><p>避免公司、家庭和投资资金混在一起</p></div><button class=\"pill\" data-go=\"input\">调整</button></div><div class=\"money-layout\"><div class=\"donut\" id=\"donut\"><div class=\"donut-center\"><b id=\"assetTotal\">¥0</b><span>全部资产</span></div></div><div class=\"legend\" id=\"wealthLegend\"></div></div></article>\n        <article class=\"card\"><div class=\"card-head\"><div><h2>财富安全分</h2><p>综合现金、负债、利润和回款</p></div><span class=\"pill\" id=\"scoreLabel\">良好</span></div><div class=\"safety\"><div class=\"score-ring\" id=\"scoreRing\"><div class=\"score\"><b id=\"score\">0</b><small>满分100</small></div></div><div class=\"checks\" id=\"checks\"></div></div></article>\n        <article class=\"card\"><div class=\"card-head\"><div><h2>未来30天，钱够不够用</h2><p>看清进账、支出和月底余额</p></div><span class=\"pill\" id=\"cashPill\">安全</span></div><div class=\"cash-grid\"><div class=\"cash-item\"><span>现在有</span><b id=\"cashNow\">¥0</b></div><div class=\"cash-item\"><span>预计收回</span><b id=\"incoming\">¥0</b></div><div class=\"cash-item\"><span>必须付出</span><b id=\"outgoing\">¥0</b></div></div><div class=\"runway\"><div class=\"runway-top\"><span>现金安全垫</span><b id=\"runwayText\">0个月</b></div><div class=\"progress\"><span id=\"runwayBar\"></span></div></div></article>\n        <article class=\"card alert-card\"><div class=\"card-head\"><div><h2>老板本周只做这3件事</h2><p>系统按风险和影响自动排序</p></div></div><div class=\"tasks\" id=\"tasks\"></div></article>\n        <article class=\"card wide\"><div class=\"card-head\"><div><h2>本月的钱是怎么留下来的</h2><p>不用看会计报表，也能看懂企业经营结果</p></div></div><div class=\"flow-row\"><div class=\"flow\"><span>卖出去</span><b id=\"flowRevenue\">¥0</b></div><div class=\"flow negative\"><span>成本和日常开支</span><b id=\"flowCost\">−¥0</b></div><div class=\"flow\"><span>最后留下</span><b id=\"flowProfit\">¥0</b></div></div></article>\n      </div>\n    </section>\n\n    <section id=\"input\" class=\"section\">\n      <header class=\"topbar\"><div><p class=\"eyebrow\">每月更新一次即可</p><h1>把关键数字告诉系统</h1></div><button class=\"btn primary\" id=\"saveData\">保存并查看结果</button></header>\n      <article class=\"card\">\n        <div class=\"form-section\"><h3>一、公司这个月赚了多少</h3><div class=\"form-grid\" id=\"businessFields\"></div></div>\n        <div class=\"form-section\"><h3>二、现在有哪些钱和资产</h3><div class=\"form-grid\" id=\"assetFields\"></div></div>\n        <div class=\"form-section\"><h3>三、未来30天的资金安排</h3><div class=\"form-grid\" id=\"cashFields\"></div></div>\n        <div class=\"form-footer\"><button class=\"btn\" id=\"clearData\">清空数字</button><button class=\"btn primary\" id=\"saveDataBottom\">保存并查看结果</button></div>\n        <p class=\"privacy\">数据按账号独立加密传输并保存在云端。建议每月固定一天更新。</p>\n      </article>\n    </section>\n\n    <section id=\"receivables\" class=\"section\">\n      <header class=\"topbar\"><div><p class=\"eyebrow\">先收钱，再扩张</p><h1>收款与负债</h1></div><button class=\"btn primary\" data-go=\"input\">更新数字</button></header>\n      <div class=\"metric-grid\"><article class=\"metric\"><span class=\"label\">客户总欠款</span><div class=\"value\" id=\"rTotal\">¥0</div><div class=\"sub\">占本月收入 <span class=\"trend\" id=\"rRatio\">0%</span></div></article><article class=\"metric risk\"><span class=\"label\">已逾期款项</span><div class=\"value\" id=\"rOverdue\">¥0</div><div class=\"sub\">建议本周重点催收</div></article><article class=\"metric\"><span class=\"label\">全部负债</span><div class=\"value\" id=\"debtTotal\">¥0</div><div class=\"sub\">公司与个人合计</div></article><article class=\"metric\"><span class=\"label\">负债占资产</span><div class=\"value\" id=\"debtRatio\">0%</div><div class=\"sub\" id=\"debtComment\">负债压力可控</div></article></div>\n      <div class=\"grid\"><article class=\"card\"><div class=\"card-head\"><div><h2>收款优先级</h2><p>先处理逾期，再处理金额最大的款项</p></div></div><div class=\"table-wrap\"><table class=\"data-table\"><thead><tr><th>款项</th><th>金额</th><th>状态</th><th>老板动作</th></tr></thead><tbody id=\"receivableRows\"></tbody></table></div></article><article class=\"card\"><div class=\"card-head\"><div><h2>负债安全线</h2><p>判断是否需要暂停新增投资</p></div></div><div class=\"checks\" id=\"debtChecks\"></div></article></div>\n    </section>\n\n    <section id=\"history\" class=\"section\">\n      <header class=\"topbar\"><div><p class=\"eyebrow\">财富变化看得见</p><h1>历史月份记录</h1></div><button class=\"btn\" onclick=\"window.print()\">打印当前报告</button></header>\n      <article class=\"card\"><div class=\"card-head\"><div><h2>已保存的财富档案</h2><p>每月保存一次，可以持续追踪利润、现金和净财富</p></div></div><div class=\"history-list\" id=\"historyList\"></div></article>\n    </section>\n\n    <section id=\"guide\" class=\"section\">\n      <header class=\"topbar\"><div><p class=\"eyebrow\">不学会计，也能管好钱</p><h1>老板使用指南</h1></div></header>\n      <div class=\"grid\"><article class=\"card\"><div class=\"card-head\"><div><h2>每周15分钟，只问5个问题</h2></div></div><div class=\"checks\"><div class=\"check\"><span class=\"check-icon\">1</span><span>今天手头真正能动用多少钱？</span></div><div class=\"check\"><span class=\"check-icon\">2</span><span>未来30天，预计收多少、必须付多少？</span></div><div class=\"check\"><span class=\"check-icon\">3</span><span>哪些客户的钱已经逾期？</span></div><div class=\"check\"><span class=\"check-icon\">4</span><span>这个月真正赚了多少钱？</span></div><div class=\"check\"><span class=\"check-icon\">5</span><span>现在最该催款、降本，还是暂停投资？</span></div></div></article><article class=\"card\"><div class=\"card-head\"><div><h2>三条资金纪律</h2></div></div><div class=\"checks\"><div class=\"check\"><span class=\"check-icon\">✓</span><span><b>公私分开：</b>个人消费不从公司账户直接支付。</span></div><div class=\"check\"><span class=\"check-icon\">✓</span><span><b>先留后分：</b>预留安全资金后，再考虑分红。</span></div><div class=\"check\"><span class=\"check-icon\">✓</span><span><b>大钱先算：</b>投入前先算多久收回、最坏损失多少。</span></div></div></article><article class=\"card wide\"><div class=\"card-head\"><div><h2>三个最容易看错的数字</h2></div></div><div class=\"flow-row\"><div class=\"flow\"><span>收入 ≠ 回款</span><b>卖了，不代表钱到了</b></div><div class=\"flow\"><span>回款 ≠ 利润</span><b>钱到了，还要扣成本</b></div><div class=\"flow\"><span>利润 ≠ 现金</span><b>赚了，也可能暂时缺钱</b></div></div></article></div>\n    </section>\n  </main>\n</div>\n<div class=\"toast\" id=\"toast\">已保存，驾驶舱已更新</div>\n<script>\n  const defaults={revenue:680000,cost:365000,expenses:168000,companyCash:860000,personalCash:260000,familyAssets:520000,investments:380000,receivable:460000,overdue:120000,inventory:310000,fixedAssets:420000,companyDebt:680000,personalDebt:180000,incoming30:360000,outgoing30:295000,monthlyFixed:185000};\n  const fields={\n    business:[['revenue','本月收入'],['cost','产品或项目成本'],['expenses','工资及日常开支'],['receivable','客户还欠你的钱'],['overdue','其中已经逾期'],['inventory','库存价值']],\n    asset:[['companyCash','公司账户现金'],['personalCash','个人可用现金'],['familyAssets','家庭资产'],['investments','投资账户'],['fixedAssets','公司设备及资产'],['companyDebt','公司负债'],['personalDebt','个人及家庭负债']],\n    cash:[['incoming30','未来30天预计收款'],['outgoing30','未来30天必须付款'],['monthlyFixed','每月固定支出']]\n  };\n  const blank=Object.fromEntries(Object.keys(defaults).map(k=>[k,0]));\n  let data={...defaults}, snapshots=[], month=new Date().toISOString().slice(0,7), demoMode=true;\n  function money(n){const a=Math.abs(Number(n)||0);if(a>=10000)return '¥'+(a/10000).toFixed(a>=1000000?0:1)+'万';return '¥'+a.toLocaleString('zh-CN')}\n  function pct(n){return Math.max(0,Number(n)||0).toFixed(1)+'%'}\n  function renderFields(){Object.entries(fields).forEach(([group,list])=>{const box=document.getElementById(group+'Fields');box.innerHTML=list.map(([key,label])=>`<div class=\"form-group\"><label for=\"${key}\">${label}</label><div class=\"input-wrap\"><span>¥</span><input id=\"${key}\" data-field=\"${key}\" type=\"number\" min=\"0\" step=\"1000\" value=\"${data[key]}\" inputmode=\"decimal\"></div></div>`).join('')})}\n  function calculate(){\n    const profit=data.revenue-data.cost-data.expenses, cash=data.companyCash+data.personalCash, assets=cash+data.familyAssets+data.investments+data.receivable+data.inventory+data.fixedAssets, debts=data.companyDebt+data.personalDebt, net=assets-debts;\n    const margin=data.revenue?profit/data.revenue*100:0, runway=data.monthlyFixed?data.companyCash/data.monthlyFixed:0, debtRatio=assets?debts/assets*100:0, overdueRatio=data.receivable?data.overdue/data.receivable*100:0, ending=data.companyCash+data.incoming30-data.outgoing30;\n    let score=100; if(runway<3)score-=25;else if(runway<6)score-=10;if(debtRatio>60)score-=25;else if(debtRatio>40)score-=10;if(margin<0)score-=25;else if(margin<10)score-=12;if(overdueRatio>30)score-=20;else if(overdueRatio>10)score-=8;score=Math.max(0,score);\n    return {profit,cash,assets,debts,net,margin,runway,debtRatio,overdueRatio,ending,score};\n  }\n  function set(id,text){document.getElementById(id).textContent=text}\n  function update(){\n    const c=calculate(); set('netWorth',money(c.net));set('profit',(c.profit<0?'−':'')+money(c.profit));set('margin',pct(c.margin));set('cash',money(c.cash));set('runwayMini',c.runway.toFixed(1)+'个月');set('receivable',money(data.receivable));set('overdue',money(data.overdue));set('assetTotal',money(c.assets));\n    set('cashNow',money(data.companyCash));set('incoming',money(data.incoming30));set('outgoing',money(data.outgoing30));set('runwayText',c.runway.toFixed(1)+'个月');document.getElementById('runwayBar').style.width=Math.min(100,c.runway/6*100)+'%';set('flowRevenue',money(data.revenue));set('flowCost','−'+money(data.cost+data.expenses));set('flowProfit',(c.profit<0?'−':'')+money(c.profit));\n    set('score',c.score);set('scoreLabel',c.score>=80?'良好':c.score>=60?'需关注':'有风险');document.getElementById('scoreRing').style.background=`conic-gradient(${c.score>=60?'var(--green)':'var(--red)'} 0 ${c.score}%,#e5ebe7 ${c.score}%)`;\n    const pockets=[['公司经营',data.companyCash+data.receivable+data.inventory+data.fixedAssets,'var(--green)'],['个人账户',data.personalCash,'var(--gold)'],['家庭保障',data.familyAssets,'#6aa694'],['财富投资',data.investments,'#c8d1cc']];const pTotal=pockets.reduce((s,x)=>s+x[1],0)||1;let acc=0,stops=[];pockets.forEach(x=>{const start=acc;acc+=x[1]/pTotal*100;stops.push(`${x[2]} ${start}% ${acc}%`)});document.getElementById('donut').style.background=`conic-gradient(${stops.join(',')})`;document.getElementById('wealthLegend').innerHTML=pockets.map(x=>`<div class=\"legend-row\"><i style=\"background:${x[2]}\"></i><span>${x[0]}</span><b>${money(x[1])}</b></div>`).join('');\n    const checkData=[[c.runway>=6,`现金可支撑 ${c.runway.toFixed(1)} 个月`],[c.margin>=10,`净利润率 ${pct(c.margin)}`],[c.debtRatio<=40,`负债占资产 ${pct(c.debtRatio)}`],[c.overdueRatio<=10,`逾期占应收 ${pct(c.overdueRatio)}`]];document.getElementById('checks').innerHTML=checkData.map(x=>`<div class=\"check ${x[0]?'':'warn'}\"><span class=\"check-icon\">${x[0]?'✓':'!'}</span><span>${x[1]}</span></div>`).join('');\n    let tasks=[];if(data.overdue>0)tasks.push([`催收逾期款 ${money(data.overdue)}`,'优先联系金额最大、逾期最久的客户']);if(c.runway<6)tasks.push(['补足现金安全垫',`距离6个月安全线还差 ${money(Math.max(0,data.monthlyFixed*6-data.companyCash))}`]);if(c.margin<15)tasks.push(['检查成本和费用','找出本月金额最大的三项支出']);if(c.debtRatio>40)tasks.push(['暂缓新增负债','先降低现有负债占比']);if(tasks.length<3)tasks.push(['确认未来30天付款计划','避免临时大额支出']);if(tasks.length<3)tasks.push(['安排本月可分配资金','先留安全垫，再决定分红']);document.getElementById('tasks').innerHTML=tasks.slice(0,3).map((x,i)=>`<div class=\"task\"><span class=\"task-num\">${i+1}</span><div><b>${x[0]}</b><small>${x[1]}</small></div><button data-go=\"${i===0&&data.overdue>0?'receivables':'input'}\">去处理</button></div>`).join('');\n    const healthy=c.runway>=3&&c.margin>=0&&c.debtRatio<60;set('statusTitle',healthy?'整体可控':'需要马上关注');set('statusText',healthy?(data.overdue>0?'现金基本安全，但逾期款需要跟进。':'当前没有明显的资金风险。'):'现金、利润或负债中存在明显风险。');document.querySelector('.status-strip').style.background=healthy?'#eaf4ef':'#fae5e3';set('cashPill',c.ending>=data.monthlyFixed?'安全':'偏紧');\n    set('rTotal',money(data.receivable));set('rOverdue',money(data.overdue));set('rRatio',pct(data.revenue?data.receivable/data.revenue*100:0));set('debtTotal',money(c.debts));set('debtRatio',pct(c.debtRatio));set('debtComment',c.debtRatio<=40?'负债压力可控':c.debtRatio<=60?'需要控制新增借款':'负债压力较高');document.getElementById('receivableRows').innerHTML=`<tr><td>已逾期客户款</td><td>${money(data.overdue)}</td><td><span class=\"tag red\">优先处理</span></td><td>本周明确回款日</td></tr><tr><td>未到期客户款</td><td>${money(Math.max(0,data.receivable-data.overdue))}</td><td><span class=\"tag green\">正常</span></td><td>到期前3天提醒</td></tr>`;document.getElementById('debtChecks').innerHTML=[[c.debtRatio<=40,'总负债不超过总资产的40%'],[c.ending>0,'未来30天现金不会转负'],[c.profit>0,'当前利润可以覆盖部分还款']].map(x=>`<div class=\"check ${x[0]?'':'warn'}\"><span class=\"check-icon\">${x[0]?'✓':'!'}</span><span>${x[1]}</span></div>`).join('');\n    bindGo();\n  }\n  function navigate(id){document.querySelectorAll('.section').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.target===id));window.scrollTo({top:0,behavior:'smooth'})}\n  function bindGo(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go))}\n  document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.target));\n  async function persist(){const response=await fetch('/api/snapshots',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({month,data})});const result=await response.json();if(!response.ok)throw new Error(result.error||'保存失败');snapshots=[result.snapshot,...snapshots.filter(x=>x.month!==month)].sort((a,b)=>b.month.localeCompare(a.month));demoMode=false;renderHistory();return result.snapshot}\n  async function save(){document.querySelectorAll('[data-field]').forEach(i=>data[i.dataset.field]=Math.max(0,Number(i.value)||0));const buttons=[document.getElementById('saveData'),document.getElementById('saveDataBottom')];buttons.forEach(b=>{b.disabled=true;b.textContent='正在保存…'});try{await persist();update();set('updatedTime','已保存到云端');document.getElementById('toast').textContent='已安全保存到云端';document.getElementById('toast').classList.add('show');setTimeout(()=>document.getElementById('toast').classList.remove('show'),2200);navigate('dashboard')}catch(error){alert(error.message||'保存失败，请稍后重试')}finally{buttons.forEach(b=>{b.disabled=false;b.textContent='保存并查看结果'})}}\n  function chooseMonth(value){month=value;document.getElementById('monthPicker').value=value;const found=snapshots.find(x=>x.month===value);data=found?{...blank,...found.data}:{...blank};demoMode=false;renderFields();update();set('updatedTime',found?'云端历史记录':'尚未保存')}\n  function renderHistory(){const box=document.getElementById('historyList');if(!snapshots.length){box.innerHTML='<div class=\"empty-state\"><b>还没有历史记录</b><p>录入并保存本月数据后，这里会自动形成月份档案。</p></div>';return}box.innerHTML=snapshots.map(s=>{const p=s.data.revenue-s.data.cost-s.data.expenses;return `<button class=\"history-item\" data-month=\"${s.month}\"><span><b>${s.month.replace('-', '年')}月</b><small>更新于 ${new Date(s.updatedAt).toLocaleDateString('zh-CN')}</small></span><span><small>本月利润</small><b>${money(p)}</b></span><span><small>公司现金</small><b>${money(s.data.companyCash)}</b></span><em>查看 →</em></button>`}).join('');box.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{chooseMonth(b.dataset.month);navigate('dashboard')})}\n  document.getElementById('saveData').onclick=save;document.getElementById('saveDataBottom').onclick=save;document.getElementById('clearData').onclick=()=>{data={...blank};demoMode=false;renderFields()};document.getElementById('resetDemo').onclick=()=>{data={...defaults};demoMode=true;renderFields();update();set('updatedTime','示例数据')};document.getElementById('monthPicker').onchange=e=>chooseMonth(e.target.value);\n  function registerWebMCP(){\n    const context=document.modelContext;if(!context?.registerTool)return;\n    const financialKeys=Object.keys(defaults);\n    try{\n      context.registerTool({name:'read_wealth_summary',title:'读取财富简报',description:'读取当前驾驶舱的净财富、利润、现金安全、应收和负债摘要，不修改任何数据。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){const c=calculate();return {netWorth:c.net,monthlyProfit:c.profit,availableCash:c.cash,cashRunwayMonths:Number(c.runway.toFixed(1)),receivables:data.receivable,overdueReceivables:data.overdue,totalDebt:c.debts,safetyScore:c.score}}});\n      context.registerTool({name:'update_financial_snapshot',title:'更新老板财务数字',description:'批量更新并云端保存当前月份的经营、资产、负债或未来30天数据。',inputSchema:{type:'object',properties:Object.fromEntries(financialKeys.map(k=>[k,{type:'number',minimum:0}])),additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){if(!input||typeof input!=='object'||Array.isArray(input))throw new Error('请输入要更新的数字');const entries=Object.entries(input);if(!entries.length)throw new Error('至少提供一个字段');for(const [key,value] of entries){if(!financialKeys.includes(key)||typeof value!=='number'||!Number.isFinite(value)||value<0)throw new Error('字段或金额无效：'+key)}Object.assign(data,input);await persist();renderFields();update();const c=calculate();return {month,updatedFields:entries.map(x=>x[0]),netWorth:c.net,monthlyProfit:c.profit,safetyScore:c.score}}});\n    }catch(error){console.warn('WebMCP registration unavailable',error)}\n  }\n  async function init(){try{const meResponse=await fetch('/api/me');if(!meResponse.ok)return;const me=await meResponse.json();set('userName',me.user.name||'老板');set('userEmail',me.user.email);document.getElementById('loginGate').hidden=true;document.getElementById('app').hidden=false;document.getElementById('monthPicker').value=month;const response=await fetch('/api/snapshots');const result=await response.json();snapshots=result.snapshots||[];const found=snapshots.find(x=>x.month===month);if(found){data={...blank,...found.data};demoMode=false;set('updatedTime','已从云端读取')}else{data={...defaults};demoMode=true;set('updatedTime','示例数据')}const date=new Date();set('today',`${date.getFullYear()}年${date.getMonth()+1}月${date.getDate()}日 · ${month.replace('-', '年')}月简报`);renderFields();update();renderHistory();bindGo();registerWebMCP()}catch(error){console.error(error)}}init();\n</script>\n</body>\n</html>\n";
